static int bind_cli_token(int argc, char **argv, int *arg_index,
                          int *args_done_p,
                          int *further_args_are_strings_p,
                          int *further_args_are_json_p,
                          const char **program_p,
                          jv *ARGS_p,
                          jq_util_input_state *input_state,
                          int *nfiles,
                          jv *lib_search_paths_p) {
  int i = *arg_index;
  int args_done = *args_done_p;
  int further_args_are_strings = *further_args_are_strings_p;
  int further_args_are_json = *further_args_are_json_p;
  const char *program = *program_p;
  jv ARGS = *ARGS_p;
  jv lib_search_paths = *lib_search_paths_p;
  int consumed = 0;

  if (args_done) {
    if (further_args_are_strings) {
      ARGS = jv_array_append(ARGS, jv_string(argv[i]));
    } else if (further_args_are_json) {
      const char *json_text = argv[i];
      int json_len = 0;
      while (json_text[json_len] != '\0') {
        json_len++;
      }
      jv_parser *parser = jv_parser_new(0);
      jv_parser_set_buf(parser, json_text, json_len, 0);
      jv value = jv_parser_next(parser);
      if (jv_is_valid(value)) {
        jv next = jv_parser_next(parser);
        if (jv_is_valid(next)) {
          jv_free(value);
          jv_free(next);
          value = jv_invalid_with_msg(jv_string("Unexpected extra JSON values"));
        } else if (jv_invalid_has_msg(jv_copy(next))) {
          jv_free(value);
          value = next;
        } else {
          jv_free(next);
        }
      } else if (jv_invalid_has_msg(jv_copy(value))) {
        value = jv_invalid_with_msg(jv_invalid_get_msg(value));
      } else {
        jv_free(value);
        value = jv_invalid_with_msg(jv_string("Expected JSON value"));
      }
      jv_parser_free(parser);
      if (!jv_is_valid(value)) {
        if (jv_invalid_has_msg(jv_copy(value))) {
          jv msg = jv_invalid_get_msg(value);
          if (jv_get_kind(msg) == JV_KIND_STRING) {
            value = jv_invalid_with_msg(jv_string_fmt("%s (while parsing '%s')",
                                                      jv_string_value(msg),
                                                      json_text));
            jv_free(msg);
          } else {
            msg = jv_dump_string(msg, 0);
            value = jv_invalid_with_msg(jv_string_fmt("%s (while parsing '%s')",
                                                      jv_string_value(msg),
                                                      json_text));
            jv_free(msg);
          }
        }
      }
      if (!jv_is_valid(value)) {
        fprintf(stderr, "%s: invalid JSON text passed to --jsonargs\n", progname);
        die();
      }
      ARGS = jv_array_append(ARGS, value);
    } else {
      jq_util_input_add_input(input_state, argv[i]);
      (*nfiles)++;
    }
    consumed = 1;
  } else if (!strcmp(argv[i], "--")) {
    if (!program) usage(2, 1);
    args_done = 1;
    consumed = 1;
  } else if (!isoptish(argv[i])) {
    if (program) {
      if (further_args_are_strings) {
        ARGS = jv_array_append(ARGS, jv_string(argv[i]));
      } else if (further_args_are_json) {
        const char *json_text = argv[i];
        int json_len = 0;
        while (json_text[json_len] != '\0') {
          json_len++;
        }
        jv_parser *parser = jv_parser_new(0);
        jv_parser_set_buf(parser, json_text, json_len, 0);
        jv value = jv_parser_next(parser);
        if (jv_is_valid(value)) {
          jv next = jv_parser_next(parser);
          if (jv_is_valid(next)) {
            jv_free(value);
            jv_free(next);
            value = jv_invalid_with_msg(jv_string("Unexpected extra JSON values"));
          } else if (jv_invalid_has_msg(jv_copy(next))) {
            jv_free(value);
            value = next;
          } else {
            jv_free(next);
          }
        } else if (jv_invalid_has_msg(jv_copy(value))) {
          value = jv_invalid_with_msg(jv_invalid_get_msg(value));
        } else {
          jv_free(value);
          value = jv_invalid_with_msg(jv_string("Expected JSON value"));
        }
        jv_parser_free(parser);
        if (!jv_is_valid(value)) {
          if (jv_invalid_has_msg(jv_copy(value))) {
            jv msg = jv_invalid_get_msg(value);
            if (jv_get_kind(msg) == JV_KIND_STRING) {
              value = jv_invalid_with_msg(jv_string_fmt("%s (while parsing '%s')",
                                                        jv_string_value(msg),
                                                        json_text));
              jv_free(msg);
            } else {
              msg = jv_dump_string(msg, 0);
              value = jv_invalid_with_msg(jv_string_fmt("%s (while parsing '%s')",
                                                        jv_string_value(msg),
                                                        json_text));
              jv_free(msg);
            }
          }
        }
        if (!jv_is_valid(value)) {
          fprintf(stderr, "%s: invalid JSON text passed to --jsonargs\n", progname);
          die();
        }
        ARGS = jv_array_append(ARGS, value);
      } else {
        jq_util_input_add_input(input_state, argv[i]);
        (*nfiles)++;
      }
    } else {
      program = argv[i];
    }
    consumed = 1;
  } else if (argv[i][1] == 'L') {
    if (jv_get_kind(lib_search_paths) == JV_KIND_NULL)
      lib_search_paths = jv_array();
    if (argv[i][2] != 0) {
      jv path = jv_string(argv[i]+2);
      int path_max;
      char *buf = NULL;
#ifdef _PC_PATH_MAX
      path_max = pathconf(jv_string_value(path), _PC_PATH_MAX);
#else
      path_max = PATH_MAX;
#endif
      if (path_max > 0) {
        buf = jv_mem_alloc(path_max);
      }
#ifdef WIN32
      char *resolved = _fullpath(buf, jv_string_value(path), path_max);
#else
      char *resolved = realpath(jv_string_value(path), buf);
#endif
      if (resolved == NULL) {
        free(buf);
      } else {
        jv_free(path);
        path = jv_string(resolved);
        free(resolved);
      }
      lib_search_paths = jv_array_append(lib_search_paths, path);
    } else if (i >= argc - 1) {
      fprintf(stderr, "-L takes a parameter: (e.g. -L /search/path or -L/search/path)\n");
      die();
    } else {
      jv path = jv_string(argv[i+1]);
      int path_max;
      char *buf = NULL;
#ifdef _PC_PATH_MAX
      path_max = pathconf(jv_string_value(path), _PC_PATH_MAX);
#else
      path_max = PATH_MAX;
#endif
      if (path_max > 0) {
        buf = jv_mem_alloc(path_max);
      }
#ifdef WIN32
      char *resolved = _fullpath(buf, jv_string_value(path), path_max);
#else
      char *resolved = realpath(jv_string_value(path), buf);
#endif
      if (resolved == NULL) {
        free(buf);
      } else {
        jv_free(path);
        path = jv_string(resolved);
        free(resolved);
      }
      lib_search_paths = jv_array_append(lib_search_paths, path);
      i++;
    }
    consumed = 1;
  }

  *arg_index = i;
  *args_done_p = args_done;
  *further_args_are_strings_p = further_args_are_strings;
  *further_args_are_json_p = further_args_are_json;
  *program_p = program;
  *ARGS_p = ARGS;
  *lib_search_paths_p = lib_search_paths;
  return consumed;
}

